import time
import databricks.sdk as dsdk
import databricks.sdk.service.ml as ml
w = dsdk.WorkspaceClient()
STORE = "mlpaba2af7c-incstore"
try:
    os_ = w.feature_store.create_online_store(ml.OnlineStore(name=STORE, capacity="CU_1"))
    print("create returned state:", os_.state)
except Exception as e:
    print("create_online_store:", repr(e)[:300])
for _ in range(150):
    try:
        s = w.feature_store.get_online_store(STORE)
    except Exception as e:
        print("get err:", repr(e)[:200]); time.sleep(10); continue
    if str(s.state).endswith("AVAILABLE"):
        print("ONLINE STORE AVAILABLE:", s.name); break
    if str(s.state).endswith("FAILED"):
        print("FAILED:", s.state); break
    time.sleep(10)
else:
    print("did not reach available in time")
'

